-- migrate:no-transaction
-- Index for the customer foreign key (and for GET /customers/:id/orders). Without it, every
-- customer delete scans all of orders to check for referencing rows. Built concurrently so
-- checkout and status updates keep writing. 0003 sets lock_timeout at session level, so reset it:
-- a CONCURRENTLY build must not be given a short lock_timeout.
RESET lock_timeout;
DROP INDEX CONCURRENTLY IF EXISTS orders_customer_id_created_at_idx;
CREATE INDEX CONCURRENTLY orders_customer_id_created_at_idx ON orders (customer_id, created_at DESC);

