-- migrate:no-transaction
-- Orders from the 2019 import point at customers that were hard-deleted back then. Re-point them at
-- the placeholder customer from 0004 so the foreign key (0007) can be enforced.
-- Walks orders by primary key in ranges and commits after each range, so row locks are held only
-- briefly and writes to orders keep flowing. Re-running is safe: only rows that still have a
-- missing customer are touched.
DO $$
DECLARE
  placeholder_id bigint;
  chunk constant bigint := 5000;
  lower_id bigint;
  upper_id bigint;
  moved bigint;
  total bigint := 0;
BEGIN
  SELECT id INTO placeholder_id FROM customers WHERE email = 'deleted-customer@internal.invalid';
  IF placeholder_id IS NULL THEN
    RAISE EXCEPTION 'placeholder customer deleted-customer@internal.invalid is missing (see 0004)';
  END IF;

  SELECT coalesce(min(id), 0), coalesce(max(id), 0) INTO lower_id, upper_id FROM orders;
  WHILE lower_id <= upper_id LOOP
    UPDATE orders o
       SET customer_id = placeholder_id
     WHERE o.id >= lower_id AND o.id < lower_id + chunk
       AND NOT EXISTS (SELECT 1 FROM customers c WHERE c.id = o.customer_id);
    GET DIAGNOSTICS moved = ROW_COUNT;
    total := total + moved;
    lower_id := lower_id + chunk;
    COMMIT;
  END LOOP;

  RAISE NOTICE 're-pointed % orphaned orders at the placeholder customer', total;
END
$$;

