import assert from 'node:assert/strict'
import { copyFile, mkdir, mkdtemp } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { test } from 'node:test'
import { PGlite } from '@electric-sql/pglite'
import { migrate } from '../src/migrate.ts'

const PLACEHOLDER = 'deleted-customer@internal.invalid'

async function migrationsUpTo(last: string): Promise<string> {
  const { readdir } = await import('node:fs/promises')
  const dir = await mkdtemp(join(tmpdir(), 'pre-orders-'))
  const names = (await readdir('migrations')).filter((f) => f.endsWith('.sql')).sort()
  await mkdir(dir, { recursive: true })
  for (const name of names) {
    if (name > last) break
    await copyFile(join('migrations', name), join(dir, name))
  }
  return dir
}

